const vert = `
precision highp float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

varying highp vec2 vTexCoord;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;

	vTexCoord = aTexCoord;
}
`;

const simulateFrag = `
precision highp float;

uniform sampler2D uSimulator;
uniform vec2 uResolution;

varying highp vec2 vTexCoord;

const float h = 1.0;
const vec2  D = vec2(0.1, 0.2);
var float f = 0.04;
var float k = 0.06;

void main(void) {
	vec2 pix = 1.0 / uResolution;
  vec2 uv0 = texture2D(uSimulator, vTexCoord).xy;
	vec2 uv1 = texture2D(uSimulator, vTexCoord + vec2(pix.x, 0.0)).xy;
	vec2 uv2 = texture2D(uSimulator, vTexCoord - vec2(pix.x, 0.0)).xy;
	vec2 uv3 = texture2D(uSimulator, vTexCoord + vec2(0.0, pix.y)).xy;
	vec2 uv4 = texture2D(uSimulator, vTexCoord - vec2(0.0, pix.y)).xy;

	vec2 laplacian = (uv1 + uv2 + uv3 + uv4 - 4.0 * uv0) / (h * h);
	float du = D.x * laplacian.x + uv0.x * uv0.x * uv0.y - (f + k) * uv0.x;
	float dv = D.y * laplacian.y - uv0.x * uv0.x * uv0.y + f * (1.0 - uv0.y);

	gl_FragColor = vec4(uv0.x + du, uv0.y + dv, 0.0, 1.0);
}
`;

const displayFrag = `
precision highp float;

uniform sampler2D uTexture;

varying highp vec2 vTexCoord;

void main(void) {
	float u = texture2D(uTexture, vTexCoord).x;
	gl_FragColor = vec4(vec3(2.0 * u), 1.0);
}
`;

