const NUM = 100;

let simulator;
let simulateShader;

let displayShader;

function setup() {
	createCanvas(800, 600, WEBGL);
	pixelDensity(1);

	simulator = createGraphics(width, height, WEBGL);
	simulator.background(0, 255, 0);
	simulator.fill(0.9 * 255, 0, 0);
	simulator.noStroke();
	for (let i=0; i<NUM; i++) {
		const x = random(-width/2, width/2);
		const y = random(-height/2, height/2);
		const d = random(2, 5);
		simulator.circle(x, y, d);
	}

	simulateShader = simulator.createShader(vert, simulateFrag);
	simulator.shader(simulateShader);
	simulateShader.setUniform('uResolution', [width, height]);

	displayShader = createShader(vert, displayFrag);
	shader(displayShader);
}

function draw() {
	background(255);

	for (let i=0; i<20; i++) {
		simulateShader.setUniform('uSimulator', simulator);
		simulator.rect(-width/2, -height/2, width, height);
	}

	displayShader.setUniform('uTexture', simulator);
	rect(-width/2, -height/2, width, height);
}
